// ViewCardReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ViewCardReadStrict(wire []byte) (*ViewCard, error) {
	var b ViewCardBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ViewCardLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ViewCardBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ViewCardBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ViewCard{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ViewCardReset((*ViewCard)(p))
	return true
}
func (b *ViewCardBuilder) GetRoot() *ViewCard {
	if b.Arena.Locked {
		return nil
	}
	return (*ViewCard)(b.Arena.At(b.root))
}
func (b *ViewCardBuilder) AsConst() *ViewCard {
	if len(b.region) == 0 {
		return nil
	}
	return (*ViewCard)(unsafe.Pointer(&b.region[0]))
}
func (b *ViewCardBuilder) Region() []byte { return b.region }
func (b *ViewCardBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ViewCardTableType(), &b.Arena)
}
func (b *ViewCardBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ViewCardTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ViewCardBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ViewCardTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ViewCardBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// WorkerViewReset restores WorkerView's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func WorkerViewReset(value *WorkerView) {
	clear(value.View[:])
	value.ViewLength = 0
	clear(value.AsName[:])
	value.AsNameLength = 0
	clear(value.Kind[:])
	value.KindLength = 0
	value.Epoch = 0
	value.Cards = TableList[ViewCardRow]{}
}

