const PacketSaveRetainMessages = "Packet: retention requires a region round trip through the VARIABLE form"

func PacketLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Packet {
	return (*Packet)(tableRegionLoadRetain(region, wire, PacketTableType(), PacketTableType().NodeType, 2, report, retain))
}
func PacketMeasureRetain(value *Packet, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), PacketTableType(), nil, true, retain, nil, allocator...)
}
func PacketSaveRetain(value *Packet, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), PacketTableType(), buffer, false, retain, report, allocator...)
}
func PacketMeasureBodyRetain(value *Packet, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !PacketSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func PacketSaveBodyRetain(w *TableRetainWriter, value *Packet) bool {
	if !PacketSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
