func PacketLoadBuilder(b *PacketBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, PacketTableType(), PacketTableType().NodeType, 2, report)
}

// PacketReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func PacketReadStrict(wire []byte) (*Packet, error) {
	var b PacketBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := PacketLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type PacketBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *PacketBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Packet{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	PacketReset((*Packet)(p))
	return true
}
func (b *PacketBuilder) GetRoot() *Packet {
	if b.Arena.Locked {
		return nil
	}
	return (*Packet)(b.Arena.At(b.root))
}
func (b *PacketBuilder) AsConst() *Packet {
	if len(b.region) == 0 {
		return nil
	}
	return (*Packet)(unsafe.Pointer(&b.region[0]))
}
func (b *PacketBuilder) Region() []byte { return b.region }
func (b *PacketBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), PacketTableType(), &b.Arena)
}
func (b *PacketBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), PacketTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *PacketBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), PacketTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *PacketBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}
func PacketNotesAdd(worker *TableWorker, holder *TableList[LineRow]) *LineRow {
	p := (*LineRow)(tableContainerAppend(worker, (*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(LineRow)))))
	if p == nil {
		return nil
	}
	LineReset(p)
	return p
}
func PacketNotesErase(arena *TableArena, holder *TableList[LineRow], element *LineRow) bool {
	return tableContainerErase(arena, (*tableContainer)(unsafe.Pointer(holder)), unsafe.Pointer(element), int64(unsafe.Sizeof(*element)))
}
func PacketNotesEach(holder *TableList[LineRow], visit func(*LineRow) bool, arena ...*TableArena) bool {
	cursor := tableContainerCursorBegin((*tableContainer)(unsafe.Pointer(holder)), int64(unsafe.Sizeof(*new(LineRow))), tableOptionalArena(arena))
	for i := int32(0); i < holder.Count; i++ {
		p := (*LineRow)(cursor.Next())
		if p == nil || !visit(p) {
			return false
		}
	}
	return true
}

// QueueCardReset restores QueueCard's declared defaults in place, reusing the storage
