func QueueCardReset(value *QueueCard) {
	clear(value.Id[:])
	value.IdLength = 0
	clear(value.TableName[:])
	value.TableNameLength = 0
	clear(value.Row[:])
	value.RowLength = 0
	clear(value.Col[:])
	value.ColLength = 0
	value.Gen = 0
	value.Attempt = 0
	value.Packet = 0
}

